def solve():
    def max_four_person_groups(n, reservedSeats):
        reserved = {}
        for row, seat in reservedSeats:
            if row not in reserved:
                reserved[row] = set()
            reserved[row].add(seat)

        count = 0
        for i in range(1, n + 1):
            row_reserved = reserved.get(i, set())
            
            # Check for groups in [2, 3, 4, 5]
            if not any(s in row_reserved for s in [2, 3, 4, 5]):
                count += 1
            
            # Check for groups in [6, 7, 8, 9]
            if not any(s in row_reserved for s in [6, 7, 8, 9]):
                count += 1
            
            # Check for groups in [4, 5, 6, 7]
            if any(s in row_reserved for s in [2,3,4,5]) and any(s in row_reserved for s in [6,7,8,9]):
                continue
            elif not any(s in row_reserved for s in [4, 5, 6, 7]):
                if any(s in row_reserved for s in [2,3,4,5]) or any(s in row_reserved for s in [6,7,8,9]):
                    continue
                else:
                    pass
            elif not any(s in row_reserved for s in [2,3,4,5]) and not any(s in row_reserved for s in [6,7,8,9]):
                count -= 1
            elif any(s in row_reserved for s in [4,5,6,7]):
                if not any(s in row_reserved for s in [2,3,4,5]) and not any(s in row_reserved for s in [6,7,8,9]):
                    count -= 1
        return count

